create or replace function public.bib_salvar_configuracao(p_nome_biblioteca text,p_prazo_padrao integer,p_prazo_maximo integer,p_renovacoes integer,p_limite integer,p_dias_alerta integer,p_permite_reserva boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_configuracoes; uid integer:=app_private.current_user_id(); tid uuid:=app_private.current_tenant_id(); begin if not exists(select 1 from public.usuarios u where u.id=uid and u.perfil in('ADMIN','BIBLIOTECARIO','BIBLIOTECARIO_RESPONSAVEL')) then raise exception 'Sem permissão para configurar a Biblioteca' using errcode='42501'; end if; insert into public.bib_configuracoes(id,tenant_id,nome_biblioteca,prazo_padrao_dias,prazo_maximo_dias,renovacoes_maximas,limite_livros_por_leitor,dias_alerta_atraso,permite_reserva,updated_at) values(1,tid,coalesce(nullif(btrim(p_nome_biblioteca),''),'Biblioteca Municipal'),greatest(1,p_prazo_padrao),greatest(p_prazo_padrao,p_prazo_maximo),greatest(0,p_renovacoes),greatest(1,p_limite),greatest(0,p_dias_alerta),coalesce(p_permite_reserva,false),now()) on conflict(id) do update set nome_biblioteca=excluded.nome_biblioteca,prazo_padrao_dias=excluded.prazo_padrao_dias,prazo_maximo_dias=excluded.prazo_maximo_dias,renovacoes_maximas=excluded.renovacoes_maximas,limite_livros_por_leitor=excluded.limite_livros_por_leitor,dias_alerta_atraso=excluded.dias_alerta_atraso,permite_reserva=excluded.permite_reserva,updated_at=now() returning * into x; perform public.bib_registrar_auditoria('CONFIGURACAO_ATUALIZADA','CONFIGURACAO',x.id::text,to_jsonb(x)); return to_jsonb(x); end; $$;
revoke execute on function public.bib_salvar_configuracao(text,integer,integer,integer,integer,integer,boolean) from public,anon; grant execute on function public.bib_salvar_configuracao(text,integer,integer,integer,integer,integer,boolean) to authenticated;

create or replace function public.bib_registrar_documento(p_entidade text,p_entidade_id text,p_nome_arquivo text,p_storage_path text,p_mime_type text,p_tamanho_bytes bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare d public.bib_documentos; tid uuid:=app_private.current_tenant_id(); begin if p_entidade not in('LIVRO','EXEMPLAR','EMPRESTIMO','DEVOLUCAO','LEITOR','INVENTARIO','AQUISICAO','DOACAO','BAIXA','EVENTO') then raise exception 'Entidade de documento inválida' using errcode='22023'; end if; if p_storage_path is null or p_storage_path not like tid::text||'/%' then raise exception 'Caminho do documento inválido' using errcode='22023'; end if; if p_tamanho_bytes<=0 or p_tamanho_bytes>26214400 then raise exception 'Documento excede 25 MB' using errcode='22023'; end if; insert into public.bib_documentos(tenant_id,entidade,entidade_id,nome_arquivo,storage_path,mime_type,tamanho_bytes,enviado_por) values(tid,p_entidade,p_entidade_id,btrim(p_nome_arquivo),p_storage_path,coalesce(nullif(p_mime_type,''),'application/octet-stream'),p_tamanho_bytes,app_private.current_user_id()) returning * into d; perform public.bib_registrar_auditoria('DOCUMENTO_ANEXADO',p_entidade,p_entidade_id,jsonb_build_object('nome',p_nome_arquivo,'tamanho',p_tamanho_bytes)); return to_jsonb(d); end; $$;
revoke execute on function public.bib_registrar_documento(text,text,text,text,text,bigint) from public,anon; grant execute on function public.bib_registrar_documento(text,text,text,text,text,bigint) to authenticated;

do $$ begin if to_regclass('storage.buckets') is not null then insert into storage.buckets(id,name,public) values('biblioteca-documentos','biblioteca-documentos',false) on conflict(id) do update set public=false; end if; end $$;
do $$ begin if to_regclass('storage.objects') is not null then drop policy if exists biblioteca_documentos_storage_insert on storage.objects; create policy biblioteca_documentos_storage_insert on storage.objects for insert to authenticated with check(bucket_id='biblioteca-documentos' and (storage.foldername(name))[1]=app_private.current_tenant_id()::text); drop policy if exists biblioteca_documentos_storage_select on storage.objects; create policy biblioteca_documentos_storage_select on storage.objects for select to authenticated using(bucket_id='biblioteca-documentos' and (storage.foldername(name))[1]=app_private.current_tenant_id()::text); drop policy if exists biblioteca_documentos_storage_delete on storage.objects; create policy biblioteca_documentos_storage_delete on storage.objects for delete to authenticated using(bucket_id='biblioteca-documentos' and (storage.foldername(name))[1]=app_private.current_tenant_id()::text); end if; end $$;
